{
  "buildCommand": "npx convex deploy --cmd 'npm run build'",
  "framework": "vite",
  "outputDirectory": "dist",
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        {
          "key": "X-Content-Type-Options",
          "value": "nosniff"
        },
        {
          "key": "X-Frame-Options",
          "value": "DENY"
        },
        {
          "key": "Referrer-Policy",
          "value": "strict-origin-when-cross-origin"
        },
        {
          "key": "Permissions-Policy",
          "value": "camera=(), microphone=(), geolocation=()"
        },
        {
          "key": "Content-Security-Policy-Report-Only",
          "value": "default-src 'self'; script-src 'self' https://valued-bonefish-64.clerk.accounts.dev; connect-src 'self' https://third-hound-186.convex.cloud wss://third-hound-186.convex.cloud https://brilliant-puma-925.convex.cloud wss://brilliant-puma-925.convex.cloud https://valued-bonefish-64.clerk.accounts.dev; img-src 'self' data: blob: https://third-hound-186.convex.cloud https://brilliant-puma-925.convex.cloud; style-src 'self' 'unsafe-inline'; worker-src 'self' blob:; frame-src https://valued-bonefish-64.clerk.accounts.dev https://challenges.cloudflare.com; base-uri 'self'; form-action 'self'"
        }
      ]
    }
  ]
}
